// ============================================================
// VALIDATE INPUT for attribute term creation
// ============================================================
// Required: attribute_id (integer), name (string)
// Optional: slug (string), description (string)

const items = $input.all();
const body = items[0]?.json?.body || items[0]?.json || {};

const attributeId = parseInt(body.attribute_id);
const name = (body.name || '').trim();
const slug = (body.slug || '').trim();
const description = (body.description || '').trim();

const errors = [];
if (!attributeId || isNaN(attributeId) || attributeId <= 0) {
  errors.push('attribute_id is required and must be a positive integer.');
}
if (!name) {
  errors.push('Term name is required.');
}

if (errors.length > 0) {
  return [{
    json: {
      _valid: false,
      _error: {
        success: false,
        message: errors.join(' ')
      }
    }
  }];
}

return [{
  json: {
    _valid: true,
    attributeId: attributeId,
    name: name,
    slug: slug || '',
    description: description || ''
  }
}];

// ============================================================
// FORMAT ATTRIBUTE TERM CREATION RESPONSE
// ============================================================
// Handle success, duplicate (term already exists), and errors.

const items = $input.all();
const data = items[0]?.json || {};

// Successful creation
if (data.id && data.name) {
  return [{
    json: {
      success: true,
      term: {
        id: data.id,
        name: data.name,
        slug: data.slug || '',
        description: data.description || '',
        count: data.count || 0
      }
    }
  }];
}

// WooCommerce error: term already exists
if (data.code === 'term_exists') {
  return [{
    json: {
      success: false,
      message: 'A term with this name already exists for this attribute.',
      existing_id: data.data?.resource_id || null
    }
  }];
}

// Other error
return [{
  json: {
    success: false,
    message: data.message || 'Failed to create attribute term.'
  }
}];

// Pass through the validation error as the response
const items = $input.all();
return [{ json: items[0].json._error }];
